# T15 – Opisy NFZ, etap 6: edycja gotowego tekstu przed zapisem (zapis, kopiowanie, otwarcie z historii, szkic, powrót do tekstu
#       z formularza), ulubione i ukryte kody, własne zestawy kodów (zasady NFZ działają jak przy ręcznym wyborze),
#       edytor stałych tekstów z szablony.js (wersje, przywracanie, zapis zaszyfrowany, zapisane wizyty bez zmian)
import sys,os; sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from h import *
import re, json
def gen(pg,age='9',plan='I',ini='jk'):
    pg.fill('#i_sv_ini',ini); pg.fill('#i_sh_age',age); pg.click(f'button.plan-btn[data-p="o5"][data-w="{plan}"]'); pg.click('#bar button.btn:not(.ghost)')
    if pg.locator('#card-ST30').count(): pg.click('#card-ST30 button[data-act="quadset"][data-q="1,2"]')
    pg.click('#bar button.btn:not(.ghost)'); idle(pg)
def body(pg,vid): return pg.evaluate(f"dbBody('{vid}').then(b=>({{t:bodyText(b),ed:!!b.ed}}))")
def fresh(pg):
    if pg.evaluate("state.step")!=3 and pg.evaluate("state.codes.length"): pg.click('#steps button[data-n="3"]'); pg.wait_for_timeout(100)
    for _ in range(2):
        if pg.evaluate("state.codes.length"): pg.click('#resetBtn'); pg.wait_for_timeout(120)
with sync_playwright() as p:
    b=launch(p); t=T(); errs=[]
    ctx=b.new_context(viewport={'width':1200,'height':900}); ctx.grant_permissions(['clipboard-read','clipboard-write'])
    pg=open_page(ctx,errs=errs)
    # ---------- edycja tekstu ----------
    gen(pg); vid=visits(pg)[0]['id']; g0=pg.evaluate("genTxt()")
    pg.click('#edTxtBtn'); t.chk('„Edytuj tekst”: pole z pełnym wygenerowanym tekstem', pg.input_value('#edTxt')==g0)
    pg.fill('#edTxt',g0+'\nDOPISEK RĘCZNY NFZ'); pg.wait_for_timeout(900); idle(pg)
    bd=body(pg,vid)
    t.chk('tekst edytowany zapisuje się w tej samej wizycie (bez dubla), ze znacznikiem „edytowany”', len(visits(pg))==1 and bd['ed'] is True and bd['t'].endswith('DOPISEK RĘCZNY NFZ'))
    pg.click('#steps button[data-n="2"]'); pg.fill('#i_sh_api','55'); pg.click('#steps button[data-n="3"]'); idle(pg)
    t.chk('zmiana w formularzu nie nadpisuje tekstu ręcznego (komunikat)', 'DOPISEK RĘCZNY NFZ' in pg.input_value('#edTxt') and 'nie został nadpisany' in pg.inner_text('#ed-note'))
    pg.click('#bar button[data-act="copyall"]') if pg.locator('#bar button[data-act="copyall"]').count() else pg.click('button[data-act="copyall"] >> nth=0')
    pg.wait_for_timeout(200); clip=pg.evaluate("navigator.clipboard.readText()")
    t.chk('„Kopiuj wszystko” kopiuje tekst edytowany', clip.endswith('DOPISEK RĘCZNY NFZ') and clip==pg.input_value('#edTxt'))
    # szkic: przejście do Kalendarza i z powrotem
    pg.click('#gbar a[data-gmod="kalendarz"]'); pg.wait_for_url('**/kalendarz.html'); pg.wait_for_function("window.Kal&&Kal.UI.loaded===true",timeout=15000)
    pg.click('#gbar a[data-gmod="nfz"]'); pg.wait_for_url('**/nfz.html'); pg.wait_for_function("typeof DB!=='undefined'&&DB.ready===true"); pg.wait_for_timeout(300)
    t.chk('po przełączeniu modułów tekst edytowany wraca (szkic)', pg.evaluate("state.ed&&state.ed.txt.endsWith('DOPISEK RĘCZNY NFZ')")==True and pg.locator('#edTxt').count()==1)
    fresh(pg)
    pg.click('#steps button[data-n="4"]'); pg.click(f'#hist-{vid} button[data-act="hopen"]'); pg.wait_for_function("state.step===3"); idle(pg)
    t.chk('„Otwórz i popraw”: wizyta z tekstem edytowanym otwiera się w trybie edycji, bez nowego zapisu', pg.locator('#edTxt').count()==1 and pg.input_value('#edTxt').endswith('DOPISEK RĘCZNY NFZ') and len(visits(pg))==1)
    pg.click('#regenBtn'); t.chk('„Wygeneruj tekst z formularza” wymaga potwierdzenia', pg.locator('#edTxt').count()==1)
    pg.click('#regenBtn'); idle(pg); pg.wait_for_timeout(300); idle(pg)
    bd=body(pg,vid)
    t.chk('…po potwierdzeniu: tekst z formularza, zapisany bez znacznika „edytowany”', pg.locator('#edTxt').count()==0 and bd['ed'] is False and 'DOPISEK' not in bd['t'] and 'API =  55' in bd['t'].replace('API = 55','API =  55') , bd['t'][:0])
    fresh(pg)
    # ---------- ulubione i ukryte kody ----------
    pg.click('#custBtn'); pg.click('#cr-ST33 button[data-act="cfav"]'); pg.click('#cr-1006 button[data-act="chid"]'); pg.click('#custBtn')
    fav=pg.locator('.group:has(h3:text-is("Ulubione")) button[data-act="code"]').all_inner_texts()
    t.chk('★ ST33 → grupa „Ulubione” na górze listy kodów', len(fav)==1 and fav[0].startswith('ST33'), fav)
    t.chk('ukryty 1006 znika z listy (informacja o ukrytych kodach)', pg.locator('button[data-act="code"][data-c="1006"]').count()==0 and 'Ukryte kody: 1 (1006)' in pg.inner_text('#main'))
    pg.fill('#codeIn','1006'); pg.click('button[data-act="addcodes"]')
    t.chk('ukryty kod można dalej wpisać ręcznie', '1006' in pg.evaluate("state.codes"))
    cfgv=pg.evaluate("LS.get('cfg',{})")
    t.chk('ulubione i ukryte zapisane w ustawieniach modułu (bez danych pacjenta)', cfgv.get('fav')==['ST33'] and cfgv.get('hid')==['1006'] and not re.search(r'JK|DOPISEK',json.dumps(cfgv)))
    pg.evaluate("()=>{state.codes=[];render();}")
    # ---------- zestawy kodów ----------
    for c in ['ST34','ST30','1101']: pg.click(f'button[data-act="code"][data-c="{c}"]')
    pg.fill('#setName','Kontrola + skaling'); pg.click('button[data-act="setsave"]')
    sets=pg.evaluate("cfg.sets")
    t.chk('„Zapisz wybrane kody jako zestaw”', len(sets)==1 and sets[0]['name']=='Kontrola + skaling' and sets[0]['codes']==['ST34','ST30','1101'])
    pg.evaluate("()=>{state.codes=['ST26'];render();}")
    pg.click(f'button[data-act="setapply"][data-id="{sets[0]["id"]}"]')
    t.chk('zestaw dodaje brakujące kody do wybranych (ST26 zostaje)', pg.evaluate("state.codes")==['ST26','ST34','ST30','1101'])
    pg.evaluate("()=>{state.codes=['ST33','ST30E'];render();}"); pg.fill('#setName','Zestaw z konfliktem'); pg.click('button[data-act="setsave"]')
    pg.evaluate("()=>{state.codes=[];render();}"); sid2=pg.evaluate("cfg.sets[1].id"); pg.click(f'button[data-act="setapply"][data-id="{sid2}"]')
    t.chk('zasady NFZ działają dla zestawu jak przy ręcznym wyborze (ST30E nie sumuje się z ST33 → błąd NFZ)', 'nie sumuje' in pg.inner_text('#main').lower() or 'nie łącz' in pg.inner_text('#main').lower(), pg.inner_text('#nfz-box') if pg.locator('#nfz-box').count() else '')
    pg.evaluate("()=>{state.codes=[];render();}")
    pg.click('#custBtn'); sid=sets[0]['id']
    pg.fill(f'input[data-setn="{sid}"]','Kontrola, skaling, lakowanie'); pg.press(f'input[data-setn="{sid}"]','Tab')
    pg.fill(f'input[data-setc="{sid}"]','st34; 23.1101 xyz ST30'); pg.press(f'input[data-setc="{sid}"]','Tab')
    t.chk('edycja zestawu: nazwa i kody (normalizacja „23.1101”, nieznane pominięte)', pg.evaluate(f"cfg.sets.find(z=>z.id==='{sid}').codes")==['ST34','1101','ST30'] and pg.input_value(f'input[data-setc="{sid}"]')=='ST34, 1101, ST30')
    pg.click(f'#set-{sid2} button[data-act="setmv"][data-d="-1"]'); t.chk('↑ zmienia kolejność zestawów', pg.evaluate("cfg.sets[0].id")==sid2)
    pg.click(f'#set-{sid} button[data-act="setfav"]'); pg.click(f'#set-{sid} button[data-act="setdup"]')
    t.chk('★ i „Duplikuj”', pg.evaluate(f"cfg.sets.find(z=>z.id==='{sid}').fav")==True and pg.evaluate("cfg.sets.length")==3)
    pg.click(f'#set-{sid2} button[data-act="setdel"]'); pg.click(f'#set-{sid2} button[data-act="setdel"]')
    t.chk('„Usuń” (2 kliknięcia)', pg.evaluate("cfg.sets.length")==2); pg.click('#custBtn')
    first=pg.locator('.plan-btns.sets button').first.inner_text()
    t.chk('ulubiony zestaw pierwszy na liście (★)', first.startswith('★ Kontrola, skaling, lakowanie'), first)
    # ---------- stałe teksty (szablony.js) ----------
    gen(pg,age='30',plan='III',ini='ab'); vold=[x for x in visits(pg) if x['ini']=='AB'][0]['id']; old_t=body(pg,vold)['t']
    t.chk('wizyta z ST33 zawiera domyślny nagłówek instruktażu', 'INSTRUKTAŻ HIGIENY JAMY USTNEJ\nPrzedstawiono dobór' in old_t)
    fresh(pg); pg.click('#steps button[data-n="6"]')
    pg.fill('#segQ','INSTR_HEAD'); pg.wait_for_timeout(100)
    t.chk('wyszukiwanie stałych tekstów', pg.locator('#seglist .crow').count()==1)
    pg.click('#sg-INSTR_HEAD button[data-act="segedit"]'); pg.fill('#segTxt','INSTRUKTAŻ HIGIENY – WERSJA GABINETU\nOmówiono technikę szczotkowania.'); pg.click('#segSave'); pg.wait_for_timeout(300)
    t.chk('zapis nowej wersji (v2, „zmieniony”)', 'zmieniony · v2' in pg.inner_text('#sg-INSTR_HEAD'))
    raw=pg.evaluate("G.store('kv').raw('nfz:seg')")
    t.chk('wersje stałych tekstów zapisane zaszyfrowane', bool(re.fullmatch(r'v1:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+',raw or '')))
    pg.click('#steps button[data-n="1"]'); gen(pg,age='30',plan='III',ini='cd'); vnew=[x for x in visits(pg) if x['ini']=='CD'][0]['id']
    t.chk('nowy opis używa nowej wersji tekstu', 'INSTRUKTAŻ HIGIENY – WERSJA GABINETU\nOmówiono technikę szczotkowania.' in body(pg,vnew)['t'])
    t.chk('wcześniej zapisana wizyta ma tekst bez zmian', body(pg,vold)['t']==old_t)
    fresh(pg); pg.reload(); pg.wait_for_function("typeof DB!=='undefined'&&DB.ready===true"); pg.wait_for_timeout(200)
    t.chk('po ponownym otwarciu wersja użytkownika obowiązuje', pg.evaluate("SEG.INSTR_HEAD").startswith('INSTRUKTAŻ HIGIENY – WERSJA GABINETU'))
    fresh(pg); pg.click('#steps button[data-n="6"]'); pg.click('#sg-INSTR_HEAD button[data-act="segedit"]')
    t.chk('historia wersji (v1 – tekst domyślny)', pg.locator('#seg-ed details .crow').count()==1)
    pg.click('#segDef'); pg.click('#segDef'); pg.wait_for_timeout(300)
    t.chk('„Przywróć tekst domyślny” (2 kliknięcia) → v3 = tekst z pliku', pg.evaluate("SEG.INSTR_HEAD===SEG0.INSTR_HEAD") and 'v3' in pg.inner_text('#sg-INSTR_HEAD') and 'zmieniony' not in pg.inner_text('#sg-INSTR_HEAD'))
    t.chk('brak błędów JS', not errs, errs[:3])
    t.done('T15 Opisy NFZ: edycja tekstu, ulubione, zestawy, stałe teksty'); b.close()
